// Variety rule: rotate the content type by weekday (Malaysia time). Config.source_override wins.
const cfg = $('Config').first().json;
const sitemaps = {
  articles: 'https://www.placidway.com/1/sitemap_articles.xml',
  answers: 'https://www.placidway.com/sitemap/1/sitemap_answers.xml',
  news: 'https://www.placidway.com/1/sitemap_news.xml',
};
const rotation = ['articles', 'articles', 'answers', 'news', 'articles', 'answers', 'news']; // Sun..Sat
const weekday = Number($now.setZone('Asia/Kuala_Lumpur').toFormat('c')) % 7; // luxon: 1=Mon..7=Sun
const type = sitemaps[cfg.source_override] ? cfg.source_override : rotation[weekday];
return [{ json: { source_type: type, sitemap_url: sitemaps[type] } }];

// Reads the sitemap, drops anything robots.txt disallows for User-agent *, newest content IDs first.
const robots = String($('Fetch robots.txt').first().json.data || '');
const xml = String($input.first().json.data || '');
const type = $('Pick content type').first().json.source_type;
if (!robots.includes('User-agent')) throw new Error('robots.txt could not be read, refusing to crawl (fail closed)');

const disallow = [];
let agents = [], lastWasAgent = false;
for (const raw of robots.split(/\r?\n/)) {
  const line = raw.split('#')[0].trim();
  if (!line.includes(':')) continue;
  const key = line.slice(0, line.indexOf(':')).trim().toLowerCase();
  const val = line.slice(line.indexOf(':') + 1).trim();
  if (key === 'user-agent') { if (!lastWasAgent) agents = []; agents.push(val.toLowerCase()); lastWasAgent = true; continue; }
  lastWasAgent = false;
  if (key === 'disallow' && val && agents.includes('*')) {
    const anchored = val.endsWith('$');
    const body = (anchored ? val.slice(0, -1) : val).replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*');
    disallow.push(new RegExp('^' + body + (anchored ? '$' : '')));
  }
}

const out = [];
for (const m of xml.matchAll(/<url>([\s\S]*?)<\/url>/g)) {
  const block = m[1];
  const loc = (block.match(/<loc>\s*([^<]+?)\s*<\/loc>/) || [])[1];
  if (!loc) continue;
  const url = loc.split('#')[0].split('?')[0];
  const path = url.replace(/^https?:\/\/[^/]+/i, '') || '/';
  if (disallow.some(re => re.test(path))) continue;
  out.push({
    url,
    source_type: type,
    content_id: Number((path.match(/\/(\d+)\//) || [])[1] || 0),
    sitemap_image: (block.match(/<image:loc>\s*([^<]+?)\s*<\/image:loc>/) || [])[1] || '',
  });
}
if (!out.length) throw new Error(`Sitemap for ${type} returned no usable URLs`);
out.sort((a, b) => b.content_id - a.content_id);
return out.slice(0, 30).map(json => ({ json }));

const pick = $('Take newest unused').first().json;
const x = $input.first().json;
const clean = s => String(s || '').replace(/\s+/g, ' ').trim();
const title = clean(x.title || x.og_title);
const body = clean(x.body).slice(0, 6000);
if (!title || body.length < 200) throw new Error(`Extraction failed for ${pick.url}: title or body missing`);
return [{ json: {
  url: pick.url,
  source_type: pick.source_type,
  title,
  description: clean(x.description),
  image_url: clean(x.image) || pick.sitemap_image || '',
  body,
  attempt: 1,
  feedback: '',
} }];

const SYSTEM = "You write one Facebook post for PlacidWay, a medical tourism marketplace, based only on the SOURCE page provided.
Hard rules:
- Use only facts stated in SOURCE. Do not add clinics, doctors, countries, statistics, dates or details that SOURCE does not state.
- No medical claims and no promises or implications of outcomes (for example: cures, guaranteed, safe, effective, painless, best results, success rate, life-changing).
- Never mention prices, costs, discounts, savings or currencies. You may say the page explains costs if SOURCE does.
- Describe what the page helps the reader learn. Do not give medical advice.
- Warm, clear, neutral tone. Plain English. No URLs.
Return only JSON with this shape:
{"hook": "one engaging line, max 110 characters",
 "value_lines": ["2 to 4 short lines, each max 120 characters, each a concrete thing the page covers"],
 "cta": "one call to action inviting people to read the full page, max 80 characters",
 "hashtags": ["3 to 5 relevant hashtags in CamelCase, no spaces"]}
Hook + value lines + CTA together must stay under 450 characters.";

const s = $input.first().json;
const cfg = $('Config').first().json;
let user = `SOURCE TITLE: ${s.title}
SOURCE DESCRIPTION: ${s.description}
SOURCE TEXT:
${s.body}`;
if (s.feedback) user += `

Your previous draft was rejected for: ${s.feedback}
Write a new draft that fixes every issue.`;
return [{ json: { ...s, llm_request: {
  model: cfg.llm_model, temperature: 0.4, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: user }],
} } }];

// Deterministic guardrail: structure, length, banned claim words, prices, numbers not in the source.
const { llm_request, ...s } = $('Build writer prompt').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content || '';
let d = null;
try { d = JSON.parse(raw.replace(/^```(json)?/i, '').replace(/```$/, '').trim()); } catch (e) {}
const issues = [];
if (!d) issues.push('writer did not return valid JSON');
const hook = String(d?.hook || '').trim();
const lines = (Array.isArray(d?.value_lines) ? d.value_lines : []).map(v => String(v).trim()).filter(Boolean);
const cta = String(d?.cta || '').trim();
const tags = (Array.isArray(d?.hashtags) ? d.hashtags : [])
  .map(t => '#' + String(t).replace(/^#+/, '').replace(/[^A-Za-z0-9]/g, '')).filter(t => t.length > 2);
if (!hook) issues.push('missing hook');
if (lines.length < 2 || lines.length > 4) issues.push(`needs 2-4 value lines, got ${lines.length}`);
if (!cta) issues.push('missing call to action');
if (tags.length < 3 || tags.length > 5) issues.push(`needs 3-5 hashtags, got ${tags.length}`);

const beforeLink = [hook, '', ...lines, '', cta].join('\n');
if (beforeLink.length >= 500) issues.push(`text before the link is ${beforeLink.length} characters (limit 499)`);
const banned = /\b(cures?|cured|guarantee[sd]?|100\s?%|risk[- ]free|painless|miracle|permanent(ly)?|proven|best results?|no side effects?|success rates?|life[- ]changing results)\b/i;
const hit = beforeLink.match(banned);
if (hit) issues.push(`blocked claim word "${hit[0]}"`);
if (/[$€£¥]|\b(usd|eur|gbp|mxn|thb|dollars?|euros?|pesos?|baht)\b/i.test(beforeLink)) issues.push('mentions a price or currency');
const source = `${s.title} ${s.description} ${s.body}`;
for (const n of beforeLink.match(/\d[\d,.]*\d|\d/g) || []) {
  if (!source.includes(n)) issues.push(`number "${n}" does not appear in the source`);
}
if (/https?:\/\/|www\./i.test(beforeLink)) issues.push('writer added a link (the workflow appends the source link itself)');

const post_text = `${beforeLink}\n\n${s.url}\n\n${tags.join(' ')}`;
return [{ json: { ...s, post_text, chars_before_link: beforeLink.length, hashtags: tags, rule_issues: issues } }];

const SYSTEM = "You are a strict compliance reviewer for medical tourism marketing posts. Compare the DRAFT with the SOURCE.
List every factual statement in the DRAFT (ignore hashtags and the link) and check it against SOURCE.
The DRAFT FAILS if it:
1. makes a medical claim or promises or implies a treatment outcome (cure, guaranteed, safe, effective, results, success),
2. mentions any price, cost figure, discount or currency, or any number that is not in SOURCE,
3. states anything SOURCE does not support.
Neutral statements about what the page covers are supported when SOURCE covers that topic (for example "Learn what to consider about costs and safety" is fine if SOURCE discusses costs and safety). Rhetorical questions and invitations to read are not claims.
Return only JSON: {"claims":[{"claim":"...","supported":true,"evidence":"short quote from SOURCE"}],"issues":["..."],"verdict":"PASS or FAIL"}";

const d = $input.first().json;
const cfg = $('Config').first().json;
const user = `SOURCE:
${d.title}
${d.description}
${d.body}

DRAFT:
${d.post_text}`;
return [{ json: { ...d, audit_request: {
  model: cfg.llm_audit_model || cfg.llm_model, temperature: 0, response_format: { type: 'json_object' },
  messages: [{ role: 'system', content: SYSTEM }, { role: 'user', content: user }],
} } }];

const { audit_request, ...d } = $('Build audit prompt').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content || '';
let a;
try { a = JSON.parse(raw.replace(/^```(json)?/i, '').replace(/```$/, '').trim()); }
catch (e) { a = { verdict: 'FAIL', issues: ['audit response was not valid JSON'] }; }
const verdict = String(a.verdict || 'FAIL').toUpperCase().includes('PASS') ? 'PASS' : 'FAIL';
const unsupported = (a.claims || []).filter(c => c.supported === false).map(c => `unsupported claim: ${c.claim}`);
const auditIssues = verdict === 'PASS' ? unsupported : [...(a.issues || []), ...unsupported];
if (verdict === 'FAIL' && !auditIssues.length) auditIssues.push('audit verdict FAIL');
const issues = [...d.rule_issues, ...auditIssues];
return [{ json: { ...d, audit_verdict: verdict, audit_claims: a.claims || [], issues, passed: issues.length === 0 } }];

const d = $input.first().json;
return [{ json: { url: d.url, source_type: d.source_type, title: d.title, description: d.description,
  image_url: d.image_url, body: d.body, attempt: d.attempt + 1, feedback: d.issues.join('; ') } }];

