const e = $json.error;
const message = String(typeof e === 'string' ? e : (e?.message || e?.description || JSON.stringify($json))).slice(0, 400);
const step = $prevNode.name;
let kind = 'Unexpected error';
if (/OAuthException|\b190\b|access token|session has expired/i.test(message)) kind = 'Facebook token expired or invalid';
else if (/Facebook/.test(step)) kind = 'Facebook API error';
else if (/LLM/.test(step)) kind = 'LLM API error';
else if (/Fetch|robots|sitemap/i.test(step)) kind = 'PlacidWay site unreachable or changed';
else if (/Extract|source record/i.test(step)) kind = 'Content extraction failed';
let released = '';
try { released = $('Combine verdict').first().json.url || ''; } catch (e) {}
return [{ json: { run_id: $('Config').first().json.run_id, step, kind, message, released_url: released } }];

